net = (categories.NET + categories.NETM) if categories.NETM else categories.NET
basic = categories.BASIC + categories.BASICM if categories.BASICM else categories.BASIC
wage = net - (categories.BO + categories.BO100) * (net / basic) if basic else 0
average_wage = payslip.i3_config_average_wage
currency = payslip.payslip_run_id.i3_currency

suspended = 0 

#get suspensions and sort them by priority  
for s in payslip.suspension_ids:
	amount = 0
	date = payslip.payslip_run_id.pay_date

	if s.start_date > date or not s.i3_active:
		continue
	
	payed = s.paid_amount

	if s.max_ratio == '3':
		ratio = 1.0 / 3.0
	elif s.max_ratio == '2':
		ratio = 1.0 / 2.0
	elif s.max_ratio == '4':
		ratio = 1.0 / 4.0
	elif s.max_ratio == '34':
		ratio = 3.0 / 4.0
	else:
		ratio = 1.0

	if s.suspension_type == 'membership':
		suspendable = 0
	elif s.max_ratio == '1':
		suspendable = wage
	elif s.max_ratio == '2':
		if wage < average_wage:
			# 1/2 of employees wage is protected => 1/2 is suspendable
			suspendable = wage * 1.0 / 2.0
		else:
			# 1/2 of average wage is protected => everything above it is suspendable
			suspendable = wage - 1.0 / 2.0 * average_wage
	elif s.max_ratio == '34':
		if wage < average_wage:
			# 1/4 of employees wage is protected => 3/4 is suspendable
			suspendable = wage * 3.0 / 4.0
		else:
			# 1/4 of average wage is protected => everything above it is suspendable
			suspendable = wage - 1.0 / 4.0 * average_wage
	else:
		if (wage *(3.0/4.0)) > (average_wage * (2.0/3.0)):
			# 2/3 of average wage is protected => everything above it is suspendable
			suspendable = wage - ((2.0/3.0) * average_wage)
		else:
			# 3/4 of employees wage is protected => 1/4 is suspendable
			suspendable = wage * (1.0/4.0)

	if s.suspension_type == 'membership':
		base = 0
		if s.membership_base == 'netto':
			base = net
		elif s.membership_base == 'brutto':
			base = basic
		amount = base * s.membership_base_pct / 100.0
	elif s.suspension_type == 'distraint':
		# if end_amount is entered -> consider it
		if s.end_amount:
			remaining = s.end_amount - (s.start_amount + s.paid_amount)
			amount = min(remaining, suspendable)
		else:
			amount = suspendable
	else:
		remaining = (s.end_amount - (s.start_amount + payed)) if s.end_amount > 0 else s.amount
		amount = s.amount if remaining >= s.amount else remaining

	take = 0     
	take_corr = 0     
	if amount > 0:
		if s.suspension_type == 'membership':
			take = amount
		elif amount < (suspendable - suspended):
			take = amount
		else:
			take = max(suspendable - suspended, 0)
		take = round(take, 2)
		if take:
			# round amount for each account and sum (this is the way suspension lines are created)
			# (else round(98.8 * 1.5%) = 1.48, but 3× round(98.8 * 0.5%) = 1.47
			# this way we get same amount for each account, even though their sum != 1.48
			for dist_line in s.bank_account_distribution_ids:
				bank_acc_amount = round(float(take * dist_line.share) / 100.0, 2)
				take_corr += bank_acc_amount
		if s.suspension_type in ('fixed','alimony') and s.amount:
			# in case there is more than one payslip in month
			# distraint and membership have no limit because they depend directly on netto or brutto salary
			# fixed_amount and alimony have monthly amounts which need to be paid so we make sure they are not overpaid
			paid_this_month = s.paid_this_month
			paid_on_this_payslip_run = payslip.get_suspension_calculated_amount(s.suspension_id)
			suspension_amount = s.amount
			to_pay = max(suspension_amount - paid_this_month - paid_on_this_payslip_run, 0)
			take_corr = min(take_corr, to_pay)
	suspended += take_corr
	if payslip.payslip_run_id.i3_profit_payment or payslip.payslip_run_id.i3_add_only_inputs or payslip.payslip_run_id.salary_in_kind:
		suspended = 0

result = suspended

