# na ugovoru je osnovica za doprinose zapisana uzevsi u obzir radno vrijeme zaposlenika (broj sati dnevno / 8 * osnovica)
# ovdje je potrebno samo napraviti korekciju obzirom na broj odradjenih dana

if payslip.payslip_run_id.salary_in_kind:
	con_base = categories.BASIC
else:
	ratio = 1
	if payslip.employee_number_of_days_at_work and payslip.employee_number_of_days_in_month:
		ratio = payslip.employee_number_of_days_at_work / payslip.employee_number_of_days_in_month
